with open(JUPITER_JS, 'r', encoding='utf-8') as f:
    content = f.read()

signs_match = re.search(r'signs:\s*\{', content)
if signs_match:
    insertion_point = signs_match.end()
    taurus_json = "      Taurus: " + json.dumps(taurus_data, indent=8) + ","
    new_content = content[:insertion_point] + "\n" + taurus_json + content[insertion_point:]
    
    with open(JUPITER_JS, 'w', encoding='utf-8') as f:
        f.write(new_content)
    print("Added Jupiter in Taurus to jupiter.js")
else:
    print("Could not find signs object in jupiter.js")
